package vista;
import controlador.LoginController;import modelo.Usuario;import javax.swing.*;import java.awt.*;
public class LoginFrame extends JFrame {private final JTextField correo=new JTextField(22);private final JPasswordField clave=new JPasswordField(22);private final LoginController controller=new LoginController();
 public LoginFrame(){super("Libroteca | Inicio de sesión");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(440,280);setLocationRelativeTo(null);setResizable(false);JPanel p=new JPanel(new GridBagLayout());p.setBorder(BorderFactory.createEmptyBorder(24,30,24,30));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(7,7,7,7);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel title=new JLabel("SISTEMA DE BIBLIOTECA ESCOLAR",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(Font.BOLD,17f));p.add(title,g);g.gridwidth=1;g.gridy++;p.add(new JLabel("Correo:"),g);g.gridx=1;p.add(correo,g);g.gridx=0;g.gridy++;p.add(new JLabel("Contraseña:"),g);g.gridx=1;p.add(clave,g);g.gridx=0;g.gridy++;g.gridwidth=2;JButton entrar=new JButton("Ingresar");p.add(entrar,g);entrar.addActionListener(e->login());clave.addActionListener(e->login());add(p);}
 private void login(){try{Usuario u=controller.login(correo.getText(),new String(clave.getPassword()));if(u==null){JOptionPane.showMessageDialog(this,"Correo o contraseña incorrectos.","Acceso denegado",JOptionPane.WARNING_MESSAGE);return;}new MenuPrincipal(u).setVisible(true);dispose();}catch(Exception e){JOptionPane.showMessageDialog(this,"No se pudo iniciar sesión: "+e.getMessage()+"\nVerifica que MySQL esté activo y la base biblioteca exista.","Error",JOptionPane.ERROR_MESSAGE);}}
}